// Version A: ids only, no pointers inside
ids := make([]int64, 10_000_000)

// Version B: one heap object per entry, reached through pointers
type Entry struct{ ID int64 }
entries := make([]*Entry, 10_000_000)
for i := range entries {
	entries[i] = &Entry{ID: int64(i)}
}

// An AI assistant's comment: "Mmap of 256 MiB raises RSS by 256 MiB at once,
// so a 128 MiB container limit is hit immediately."
b, err := syscall.Mmap(-1, 0, 256<<20,
	syscall.PROT_READ|syscall.PROT_WRITE,
	syscall.MAP_ANON|syscall.MAP_PRIVATE)
if err != nil {
	panic(err)
}

// later: touch one byte in every 4 KiB page of the first 64 MiB
for i := 0; i < 64<<20; i += 4096 {
	b[i] = 1
}
